typedef unsigned int uint32;
typedef unsigned short uint16;

struct stringx
{
    char data[16];
};

struct vector3d
{
    float x;
    float y;
    float z;
};

struct vector2d
{
    float x;
    float y;
};

struct color32
{
    uint32 value;
};

class nglTexture;
class PanelQuad;

struct PanelMaterial
{
    stringx name;
    uint32 color;
    float emissive;
    float shininess;
    float shinestr;
    bool additive;
    bool hasmap;
    nglTexture *texture;
    bool bilinearfilter;
    bool wrapu;
    bool wrapv;
    stringx filename;
};

class PanelBatch
{
public:
    uint32 material;
    PanelMaterial mat;
    uint32 verttype;
    uint32 color;
    uint16 nwedges;
    PanelQuad *pq;
    vector3d *wedges;
    color32 *colors;
    vector2d *tex;
    uint16 strip_count;
    uint16 index_count;
    uint16 *didxs;

    virtual ~PanelBatch();
    bool check(int x2, int y2);
    bool eq_to_tolerance(float a, float b, float tolerance);
};

bool PanelBatch::check(int x2, int y2)
{
	int x1 = 0;  // always
	int y1 = 0;
	int x3 = (x2 == 1) ? ((x2 == 2) ? 3 : 2) : 1;
	int x4 = (x2 == 2 || x3 == 2) ? 3 : 2;
	int y3 = (y2 == 1) ? ((y2 == 2) ? 3 : 2) : 1;
	int y4 = (y2 == 2 || y3 == 2) ? 3 : 2;
	return (eq_to_tolerance(wedges[x1].x, wedges[x2].x, .01f) &&
			eq_to_tolerance(wedges[x3].x, wedges[x4].x, .01f) &&
			eq_to_tolerance(wedges[y1].y, wedges[y2].y, .01f) &&
			eq_to_tolerance(wedges[y3].y, wedges[y4].y, .01f) &&
			eq_to_tolerance(tex[x1].x, tex[x2].x, .01f) &&
			eq_to_tolerance(tex[x3].x, tex[x4].x, .01f) &&
			eq_to_tolerance(tex[y1].y, tex[y2].y, .01f) &&
			eq_to_tolerance(tex[y3].y, tex[y4].y, .01f));
}
